(function(){var burger=document.querySelector('[data-dash-burger]');var side=document.getElementById('dash-side');if(burger&&side){burger.addEventListener('click',function(){side.classList.toggle('is-open');});document.addEventListener('click',function(e){if(!side.classList.contains('is-open'))return;if(side.contains(e.target)||burger.contains(e.target))return;side.classList.remove('is-open');});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&side.classList.contains('is-open')){side.classList.remove('is-open');}});}
var copyButtons=document.querySelectorAll('[data-dash-copy]');copyButtons.forEach(function(btn){btn.addEventListener('click',async function(){var path=btn.getAttribute('data-copy-link')||'/';var url=window.location.origin+path;var orig=btn.textContent;try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(url);}else{var ta=document.createElement('textarea');ta.value=url;ta.setAttribute('readonly','');ta.style.position='absolute';ta.style.left='-9999px';document.body.appendChild(ta);ta.select();document.execCommand('copy');document.body.removeChild(ta);}
btn.textContent='Copied';setTimeout(function(){btn.textContent=orig;},1500);}catch(err){btn.textContent=url;setTimeout(function(){btn.textContent=orig;},3000);}});});var counter=document.querySelector('[data-profile-counter]');var display=document.querySelector('[data-profile-counter-display]');if(counter&&display){var max=counter.getAttribute('data-profile-counter-max')||'280';counter.addEventListener('input',function(){display.textContent=counter.value.length+' / '+max;});}})();